function is_drink_category($category) { return preg_match('/cà phê|espresso|cold brew|trà|matcha|chocolate|đá xay|sữa|soda|sinh tố|đồ uống|nước ép/iu', (string)$category) === 1; }
function drink_percent($value) { $allowed=[0,25,50,75,100];$value=(int)$value;return in_array($value,$allowed,true)?$value:100; }
